begin;

alter table public.product_catalog add column if not exists concerns jsonb not null default '[]'::jsonb;
alter table public.product_catalog add column if not exists primary_concern text;

insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('d-connect-pelvic-floor-fitness', 'Connect Pelvic Floor Fitness', 'Connect Pelvic Floor Fitness', 'pelvic-floor', 'digital', 'A pelvic-floor-informed fitness program founded by Caroline Packard, DPT, after her own postpartum stress incontinence and prolapse. Combines pelvic floor rehab principles with real strength training, HIIT, yoga, and mobility work to build pelvic floor and whole-body strength.', '$30/month or $180/year (14-day free trial; HSA/FSA eligible)', 'https://is1-ssl.mzstatic.com/image/thumb/Purple221/v4/b1/39/0f/b1390fbf-2c51-b7ff-af3b-b9a7660f4b9c/AppIcon-0-0-1x_U007emarketing-0-8-0-85-220.png/512x512bb.jpg', 'https://connectpelvicfloorfitness.com/', '["pelvic-floor","leaks","discomfort","postpartum","fitness","prolapse"]'::jsonb, '["vaginal-health"]'::jsonb, '[]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Fitness and education service; not a medical device.","materials":"N/A","recalls":"N/A","sideEffects":"Exercise programs may not be appropriate for every pelvic floor condition. Stop if exercises cause pain or worsen symptoms and consult a pelvic floor physical therapist or clinician when needed. Diastasis recti evidence for exercise alone is limited (see Clinician opinion below): anyone with a significant abdominal separation should be evaluated by a clinician before relying on exercise as a sole treatment.","opinionAlerts":"Program information is based on the brand''s own description; individual results depend on the specific condition, adherence, and guidance from a clinician when needed."}'::jsonb, 'This program''s core approach (pelvic floor muscle training (PFMT)) has real, strong independent evidence behind it for two of the conditions it targets. A Cochrane systematic review of 31 trials in 1,817 women found PFMT can cure or improve stress and other types of urinary incontinence, and is recommended as part of first-line conservative management. A separate systematic review and meta-analysis of 13 trials in 2,340 women found PFMT produced greater subjective and objective improvement in pelvic organ prolapse symptoms and stage compared to controls.

Evidence for exercise specifically correcting diastasis recti (abdominal separation) is more limited. A recent systematic review and meta-analysis found no clear evidence that exercise-based interventions alone reduce inter-recti distance in postpartum women, though exercise may still provide functional or symptomatic benefit even without measurably closing the gap.

These citations are for pelvic floor muscle training and postpartum exercise generally: no independent study of this specific program''s protocol was found.', 'Reviews on Connect''s own site and app store listings include: "How Caroline explains things and how this app is set up is 100 out of 10," and "I wholeheartedly recommend this program to anyone who has been told to live with symptoms or that surgery is the only option. It has transformed my approach to fitness and my overall well-being." No independently verifiable aggregate star rating was found on the Apple App Store at time of writing.', 'Built on pelvic floor muscle training, which has strong independent evidence for improving urinary incontinence and pelvic organ prolapse; evidence for exercise alone correcting diastasis recti is more limited. Individual results vary, and no independent study of this specific program was found.', 'brand', 'Program is designed by Caroline Packard, DPT, a pelvic floor physical therapist with 15+ years of clinical experience. Description sourced from Connect Pelvic Floor Fitness; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"platform":"Web, app, Roku, Amazon Fire TV, Apple TV","affiliateUrl":"https://goto.connectpelvicfloorfitness.com/YVk7WO","ingredients":"Not a physical product: see \"How it works\" below for what the membership includes.","doctorOpinionShort":"Pelvic floor muscle training (the program''s core approach) has strong independent evidence for improving urinary incontinence and pelvic organ prolapse symptoms specifically. Evidence for exercise alone correcting diastasis recti is more limited. No independent study of this specific program''s protocol was found.","doctorOpinionCitations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/25408383/","label":"PubMed: Pelvic floor muscle training for urinary incontinence in women, a Cochrane systematic review"},{"url":"https://pubmed.ncbi.nlm.nih.gov/26407564/","label":"PubMed: The efficacy of pelvic floor muscle training for pelvic organ prolapse, a systematic review and meta-analysis"}],"whoItsFor":["Postpartum women dealing with leakage, prolapse symptoms, or diastasis recti","Women who want strength training that''s built around pelvic floor function rather than around it","Anyone told their only options were \"live with it\" or surgery, who wants to try a structured conservative program first","Women wanting DPT-designed programming without needing to attend in-person physical therapy"],"howToUse":{"intro":"Per Connect''s own site: start with a 14-day free trial, then continue on a monthly or annual membership.","steps":["Access a growing library of strength training, HIIT, advanced core, yoga, and mobility workouts, each 35–45 minutes and fully guided, with instruction on form, breathing, and modifications.","Use built-in self-assessments throughout to track progress and guide what to do next.","Join monthly live Q&A sessions with Caroline Packard, DPT.","Get access to a private members-only community and pelvic floor educational resources.","Stream on the website, the iOS/Android app, or Roku, Amazon Fire TV, and Apple TV.","HSA/FSA eligible through Connect''s partner Flex, per the brand''s site."],"sourceUrl":"https://connectpelvicfloorfitness.com/membership","sourceLabel":"connectpelvicfloorfitness.com: Membership"},"warnings":["Not a substitute for an in-person pelvic floor physical therapy evaluation, especially for significant prolapse, diastasis recti, or persistent leakage.","Stop any exercise that causes pain or worsens symptoms and consult a pelvic floor physical therapist or clinician.","Cancel at least 24 hours before renewal to avoid being charged for the next billing period, per the brand''s site."],"scientificCitations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/25408383/","text":"PubMed: Pelvic floor muscle training for urinary incontinence in women, a Cochrane systematic review","summary":"21 trials, 1,281 women. Found PFMT is associated with cure or improvement of stress and other types of urinary incontinence, general evidence for the training approach, not this specific program."},{"url":"https://pubmed.ncbi.nlm.nih.gov/26407564/","text":"PubMed: The efficacy of pelvic floor muscle training for pelvic organ prolapse, a systematic review and meta-analysis","summary":"13 trials, 2,340 women. Found PFMT improved both subjective prolapse symptoms and objective prolapse severity versus controls."},{"url":"https://pubmed.ncbi.nlm.nih.gov/41995773/","text":"PubMed: What is the evidence for abdominal and pelvic floor muscle training to treat diastasis recti abdominis postpartum?, an updated systematic review and meta-analysis","summary":"Found no clear evidence that exercise-based interventions alone reduce inter-recti distance, though exercise may still help function/symptoms. Included for balance, this is a more cautious finding than the incontinence/prolapse evidence above."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[{"url":"https://pubmed.ncbi.nlm.nih.gov/30704907/","text":"Pelvic Floor Muscle Training for Urinary Incontinence: Cochrane Review","summary":"A Cochrane systematic review supports pelvic floor muscle training for women with stress, urgency, or mixed urinary incontinence. Evidence supports PFMT generally and does not validate the Connect program specifically.","justification":"Peer-reviewed Cochrane systematic review; intervention-level evidence."}]},"community":{"links":[{"platform":"website","url":"https://connectpelvicfloorfitness.com/faqs","text":"connectpelvicfloorfitness.com: FAQs","summary":"Connect''s own FAQ page, covering membership details, cancellation, and program logistics."},{"platform":"website","url":"https://apps.apple.com/us/app/connect-pelvic-floor-fitness/id6475697994","text":"Apple App Store: Connect Pelvic Floor Fitness","summary":"Real, current App Store listing. Review content/ratings weren''t independently verifiable at time of writing, read them directly on the page."},{"platform":"website","url":"https://play.google.com/store/apps/details?id=com.VidApp.ConnectPelvicFloor","text":"Google Play: Connect Pelvic Floor Fitness","summary":"Real, current Google Play listing. Review content/ratings weren''t independently verifiable at time of writing, read them directly on the page."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-proov-path-to-pregnancy', 'Proov Clinical: F.A.S.T. Method, Path to Pregnancy', 'Proov', 'telehealth', 'physical', 'A 3-month at-home fertility optimization program combining monthly Proov Complete and Check kits with review by a reproductive endocrinologist (Dr. Aimee''s F.A.S.T. Method), including prescription support (capped cost) if a user qualifies.', '$399 (3-month program)', '/products/catalog/p-proov-path-to-pregnancy.webp', 'https://proovtest.com/products/path-to-pregnancy', '["fertility","irregular"]'::jsonb, '["fertility","telehealth"]'::jsonb, '[]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Combines the FDA-cleared Proov PdG test technology (510(k) K191462) with prescription medication support issued by a licensed provider, not the kits themselves.","materials":"3 Proov Complete kits (hormone tests) + 3 Proov Check kits (early pregnancy tests) + clinician-reviewed protocol.","recalls":"No recalls found.","sideEffects":"Any medication side effects depend on what a provider prescribes (letrozole, progesterone, or metformin per the brand).","opinionAlerts":"Brand states eligibility excludes anyone with a history of cancer, unexplained vaginal bleeding, liver disease, BMI over 49.9, or who is more than 10 weeks pregnant. Verify current eligibility criteria on proovtest.com."}'::jsonb, 'This program is reviewed per the brand by Dr. Aimee Eyvazzadeh, MD, MPH: a real, practicing reproductive endocrinologist trained at UCLA, Harvard, and the University of Michigan, known publicly as "The Egg Whisperer," and a genuine medical advisor to Proov. That''s a verifiable, legitimate credential, though ayna hasn''t independently confirmed her personal, direct review of every individual program participant''s results.

The program combines Proov''s FDA-cleared PdG/hormone testing (see Proov Complete''s entry for that technology''s validation) with clinician-reviewed, capped-cost prescription support across three cycles. No independent study of program-level outcomes (pregnancy rates, time-to-conception) for this specific 3-month protocol was found.', 'No independently verified rating specific to this program was found; see Proov''s general reviews (181 reviews, 4.43/5 on reviews.io) for brand-level feedback.', 'Bundles three months of FDA-cleared hormone/pregnancy testing with review by a real, credentialed reproductive endocrinologist and possible capped-cost prescription support; no independent study of program-level outcomes was found.', 'brand', 'Reviewed per the brand by Dr. Aimee Eyvazzadeh, MD, MPH, a real, practicing reproductive endocrinologist and Proov medical advisor, as part of the F.A.S.T. Method; ayna hasn''t independently verified her direct review of individual program results.', 'curated', false, false, null, true, '{"affiliateUrl":"https://proov.pxf.io/zz52BW","doctorOpinionShort":"Dr. Aimee Eyvazzadeh, the reviewing physician named by the brand, is a real, credentialed reproductive endocrinologist and a genuine Proov medical advisor. The underlying hormone-testing technology is FDA-cleared and independently validated; program-level outcomes for this specific 3-month protocol haven''t been independently studied.","doctorOpinionCitations":[{"url":"https://eggwhisperer.com/about/","label":"Dr. Aimee Eyvazzadeh (Egg Whisperer): credentials and background"}],"whoItsFor":["Women wanting a lower-cost, at-home alternative to an initial fertility clinic workup, with real clinician review built in","Anyone who wants monthly hormone/pregnancy testing plus a path to prescription support without starting at a full clinic"],"howToUse":{"intro":"Per Proov''s own site: complete monthly testing across 3 cycles while a reproductive endocrinologist reviews your results.","steps":["Test each cycle with a Proov Complete kit (hormone tests) and Proov Check kit (early pregnancy tests).","Results are reviewed against the F.A.S.T. Method protocol.","If you qualify, get capped-cost prescription support (letrozole, progesterone, or metformin per the brand) through a licensed provider.","Continue for up to 3 cycles."],"sourceUrl":"https://proovtest.com/products/path-to-pregnancy","sourceLabel":"proovtest.com: Path to Pregnancy"},"warnings":["Not eligible if you have a history of cancer, unexplained vaginal bleeding, liver disease, a BMI over 49.9, or are more than 10 weeks pregnant, per the brand: verify current eligibility on proovtest.com.","Any prescribed medication (letrozole, progesterone, or metformin) carries its own real side-effect profile: discuss with the prescribing provider.","Not a substitute for in-person fertility clinic care if you need procedures like IUI or IVF."],"scientificCitations":[{"url":"https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpmn/pmn.cfm?ID=K191462","text":"FDA 510(k) K191462, MFB Fertility, Inc.","summary":"The FDA clearance record for the Proov PdG test technology used across this program''s monthly testing."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://www.reviews.io/company-reviews/store/proov-test","text":"reviews.io: Proov Test reviews","summary":"Independent, third-party review platform, 181 reviews, 4.43/5 average at time of writing (covers Proov overall, not this program specifically)."},{"platform":"tiktok","url":"https://www.tiktok.com/tag/proov","text":"TikTok: #proov","summary":"Real, current TikTok hashtag page aggregating Proov-related content (brand-wide, not specific to this program). Individual video claims are user-generated and not independently verified here."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-gina-starter-kit', 'gina The Starter Kit', 'gina', 'intimate-care', 'physical', 'gina''s starter bundle for vaginal dryness, irritation, or discomfort during intimacy, at any life stage: perimenopause, menopause, postpartum, or day to day. It includes a one-month supply of its coconut-oil Vaginal Moisturizing Glides (pack of 12), plus disposable finger sleeves, an insertion applicator, a free cotton pouch, a brochure guide, and free wellness advice from gina''s nurse practitioner team. The glides are non-hormonal, single-ingredient suppositories of 100% pure, extra virgin, unrefined, cold-pressed coconut oil, with no fillers or artificial ingredients.', '$48.00 (list $63)', '/products/catalog/p-gina-starter-kit.webp', 'https://getgina.com/products/the-starter-kit', '["discomfort","comfort","organic","non-hormonal","cruelty-free","non-toxic","ph-neutral","single-use","clinician-informed","starter kit","bundle"]'::jsonb, '["vaginal-health"]'::jsonb, '["getgina.com"]'::jsonb, '{}'::jsonb, '{"materials":"Contents per gina: 12 Vaginal Moisturizing Glides (100% pure, extra virgin, unrefined, cold-pressed coconut oil; 1.72 g each), disposable finger sleeves, an insertion applicator, a cotton pouch, and a brochure guide. gina doesn''t state what the finger sleeves are made of.","recalls":"No recalls found.","sideEffects":"Discontinue and see a doctor if you notice irritation or an allergic reaction. Coconut oil is oil-based and can weaken latex condoms. Full warnings are listed below."}'::jsonb, 'The Starter Kit bundles gina''s coconut-oil Vaginal Moisturizing Glides with the tools for inserting them, at $48 compared with a $63 list price. gina says the glides hydrate and condition vaginal tissue and soothe discomfort, including during intimacy.

There''s real clinical evidence behind coconut oil for this use: a 2023 pilot study followed 53 women using virgin coconut oil for vaginal dryness and painful sex over 6 months, and most reported real improvement. It wasn''t placebo-controlled and didn''t test this specific product. No independent clinical study of gina''s glides was found.', 'gina''s product page lists 18 reviews for The Starter Kit, but no star rating is shown alongside the count. The glides inside the kit are reviewed separately on gina''s glides page.', 'Clinical evidence supports coconut oil for vaginal dryness generally, though no independent study has tested gina''s glides specifically.', 'brand', 'Sourced from gina''s own site marketing claims, not independent clinical literature.', 'curated', true, false, null, true, '{"doctorOpinionShort":"A starter bundle of gina''s single-ingredient coconut-oil glides plus insertion tools. A 2023 pilot study found most of 53 women using coconut oil for vaginal dryness reported improvement, though it wasn''t placebo-controlled; no independent study of this product was found.","doctorOpinionCitations":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10350307/","label":"Cureus (2023): Virgin coconut oil for dyspareunia and vaginal dryness, pilot study, 53 women","chipLabel":"Read the 2023 study (NIH) →"}],"whoItsFor":["People trying gina for the first time who want the glides and every insertion option in one box","Vaginal dryness or discomfort at any life stage, including perimenopause, menopause and postpartum","People who prefer a single-ingredient, hormone-free option"],"howToUse":{"intro":"Per gina''s own site: if you''re new to vaginal care or have extreme dryness, start with finger or finger-sleeve insertion for greater comfort, then try the applicator.","steps":["Empty your bladder, clean the area, and wash your hands.","Separate a single chilled glide, wait 1 to 3 minutes, then peel back the foil.","Squeeze to pop the glide out onto a clean surface.","Insert with a finger, a finger sleeve, or the applicator while lying on your back with your knees raised.","Wait 3 minutes, or until it''s fully melted."],"sourceUrl":"https://getgina.com/pages/how-to-use-moisturizing-glides","sourceLabel":"getgina.com: How to Use Moisturizing Glides"},"warnings":["Oil-based: can weaken latex condoms.","Latex allergy: gina doesn''t say what the finger sleeves are made of, so check with gina before using them.","Pregnant or breastfeeding: check with a doctor first.","Irritation or an allergic reaction: stop using it and see a doctor."],"ingredients":"Glides: coconut oil (100% pure, extra virgin, unrefined, cold-pressed). Kit also includes finger sleeves, an applicator, a pouch and a guide.","ingredientScience":[{"name":"Coconut oil (100% pure, extra virgin, unrefined, cold-pressed)","text":"A natural moisturizer rich in lauric acid. In a randomized, double-blind clinical trial, topical virgin coconut oil improved skin barrier function (lower transepidermal water loss, higher skin capacitance) more than mineral oil.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24320105/","label":"PubMed: Topical virgin coconut oil in pediatric atopic dermatitis, a randomized, double-blind clinical trial"}]}],"scientificCitations":[{"url":"https://www.acog.org/womens-health/faqs/vulvovaginal-health","text":"ACOG: Vulvovaginal Health","summary":"ACOG notes that over-the-counter vaginal moisturizers and lubricants can help relieve vaginal dryness and painful sex. This is clinical-guidance-level evidence, not product-specific validation."},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10350307/","text":"Virgin Coconut Oil in Paste Form as Treatment for Dyspareunia and Vaginal Dryness in Patients With and Without Rheumatic Autoimmune Diseases: An Efficacy and Safety Assessment Pilot Study","summary":"A 2023 pilot survey study (Cureus) of 53 women who used a virgin coconut oil paste for vaginal dryness and painful sex found dryness decreased in both of its groups, with no side effects reported. It had no control group and didn''t test gina''s product."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://getgina.com/products/the-starter-kit","text":"getgina.com: The Starter Kit reviews","summary":"gina''s product page lists 18 reviews for the kit, without a star rating shown."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-happyhead-hair-growth-supplements', 'Happy Head Hair Growth Supplements', 'Happy Head', 'supplement', 'physical', 'A daily, drug-free hair supplement from Happy Head, a hair-loss company that also offers dermatologist-prescribed treatments. The blend''s headline ingredients are biotin, collagen, keratin, saw palmetto, ashwagandha, and vitamins A and D (full list under Ingredients). Happy Head says it supports healthier hair and scalp and visibly thicker hair in 3 to 6 months. Take 2 capsules daily with a meal; a jar of 60 capsules lasts a month. No prescription needed.', '$79 for 60 capsules (1 month); $67/month with a subscription', '/products/catalog/p-happyhead-hair-growth-supplements.webp', 'https://www.happyhead.com/products/hair-growth-supplements', '["happyhead","hair","hair growth","hair thinning","biotin","saw palmetto","ashwagandha","collagen","supplement","drug-free"]'::jsonb, '["supplement","skin-hair"]'::jsonb, '["happyhead.com"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not evaluated by the FDA for safety or efficacy claims.","materials":"60 capsules per jar (2 a day, 1-month supply). Happy Head doesn''t publish a Supplement Facts panel with ingredient amounts on its product page. Store in a cool, dry place; no refrigeration needed.","recalls":"No recalls found.","sideEffects":"Contains ashwagandha. The NIH says ashwagandha should be avoided during pregnancy and breastfeeding, isn''t recommended for people with thyroid or autoimmune disorders or before surgery, has been linked to rare cases of liver injury, and may interact with medicines for diabetes, blood pressure, thyroid, seizures and immune suppression, and with sedatives. Happy Head says to consult a physician if you are pregnant, nursing or planning to become pregnant. It also contains biotin, which the FDA warns can interfere with certain lab tests. Full warnings are listed below.","opinionAlerts":"Contains ashwagandha, which the NIH says to avoid during pregnancy and breastfeeding and with thyroid or autoimmune conditions. Happy Head doesn''t publish ingredient amounts, so its doses can''t be compared with the studies below."}'::jsonb, 'Happy Head says this dermatologist-developed blend supports fuller, thicker, stronger hair in 3 to 6 months. No independent study of this product was found, and Happy Head doesn''t publish its ingredient amounts, so what follows is what the research says about its main ingredients.

A 2023 JAMA Dermatology systematic review of 30 studies of supplements for hair loss in people without a known nutritional deficiency found the best evidence for specific products (Viviscal, Nourkrin, Nutrafol and others) and some single ingredients, with rare, mild side effects. It called for larger trials with active comparators.

Biotin is the most popular hair ingredient but has the weakest case: a 2017 review found it helped only in people with an underlying cause such as biotin deficiency, and found no good evidence for healthy people. Saw palmetto has more support: a 2020 systematic review of 5 randomized trials and 2 other studies found oral or topical saw palmetto (100–320 mg) improved hair quality and density in people with pattern hair loss or shedding, though high-quality data are lacking. Saw palmetto is anti-androgenic.

Ashwagandha is the main safety concern for women: the NIH says to avoid it during pregnancy and breastfeeding, and with thyroid or autoimmune disorders.', null, 'Saw palmetto has modest, low-quality evidence for pattern hair loss and shedding; biotin hasn''t been shown to help people who aren''t deficient.', 'brand', 'Product claims are sourced from Happy Head; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"ingredients":"Per Happy Head: biotin, collagen, keratin, saw palmetto, ashwagandha, probiotics, vitamin A, vitamin D. Happy Head doesn''t publish the amount of each ingredient on its product page.","doctorOpinionShort":"Saw palmetto has modest evidence for pattern hair loss; biotin helps only if you''re deficient. Happy Head doesn''t publish ingredient amounts, and no independent study of this product was found. It contains ashwagandha, which the NIH says to avoid during pregnancy, breastfeeding, and with thyroid or autoimmune conditions.","doctorOpinionCitations":[{"url":"https://www.happyhead.com/products/hair-growth-supplements","label":"happyhead.com: Hair Growth Supplements, ingredients and claims"},{"url":"https://www.nccih.nih.gov/health/ashwagandha","label":"NIH NCCIH: Ashwagandha, safety"},{"url":"https://pubmed.ncbi.nlm.nih.gov/36449274/","label":"PubMed: Evaluation of the safety and effectiveness of nutritional supplements for treating hair loss, systematic review (JAMA Dermatol 2023)","chipLabel":"Hair supplements review, JAMA Derm (2023)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/28879195/","label":"PubMed: A review of the use of biotin for hair loss","chipLabel":"Biotin for hair loss review (2017)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/33313047/","label":"PubMed: Natural hair supplement, friend or foe? Saw palmetto, a systematic review in alopecia","chipLabel":"Saw palmetto systematic review (2020)"}],"whoItsFor":["Adults with thinning hair looking for a drug-free supplement, ideally after a clinician has checked for causes like iron or thyroid problems","Not for pregnancy, breastfeeding, or trying to conceive, or for people with thyroid or autoimmune conditions (ashwagandha)"],"howToUse":{"intro":"Per Happy Head: take consistently for 3 to 6 months to see results.","steps":["Take 2 capsules by mouth daily with a meal.","Store in a cool, dry place with the lid tightly closed."],"sourceUrl":"https://www.happyhead.com/products/hair-growth-supplements","sourceLabel":"happyhead.com: Hair Growth Supplements"},"warnings":["Pregnant, breastfeeding, or trying to conceive: the NIH says to avoid ashwagandha; Happy Head says to consult your physician first.","Thyroid or autoimmune condition, or surgery coming up: the NIH doesn''t recommend ashwagandha.","Taking medicine for diabetes, blood pressure, thyroid, seizures, or immune suppression, or sedatives: ashwagandha may interact, so check with your doctor.","Contains biotin: the FDA warns biotin can interfere with certain lab tests, so tell your doctor before blood work.","Signs of liver problems: stop and see a doctor; the NIH notes rare liver injury linked to ashwagandha."],"ingredientScience":[{"name":"Supplements for hair loss (overall evidence)","text":"A 2023 JAMA Dermatology systematic review of 30 studies (17 randomized trials) in people without a known nutritional deficiency found the highest-quality evidence for specific branded supplements and some single ingredients. Side effects were rare and mild. The authors called for larger trials against active treatments.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/36449274/","label":"PubMed: Evaluation of the safety and effectiveness of nutritional supplements for treating hair loss, systematic review (Drake et al., JAMA Dermatol 2023)"}]},{"name":"Biotin","text":"A 2017 review found 18 reported cases where biotin improved hair or nails, all in people with an underlying problem such as biotin deficiency. The authors concluded there isn''t enough evidence for biotin supplements in healthy people. The FDA also warns biotin can interfere with certain lab tests.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28879195/","label":"PubMed: A review of the use of biotin for hair loss (Patel et al., 2017)"},{"url":"https://www.fda.gov/medical-devices/in-vitro-diagnostics/biotin-interference-troponin-lab-tests-assays-subject-biotin-interference","label":"FDA: Biotin interference with lab tests"}]},{"name":"Saw palmetto","text":"A 2020 systematic review of 5 randomized trials and 2 other studies found oral or topical saw palmetto (100–320 mg) improved overall hair quality, hair count and density in people with pattern hair loss and shedding, and was well tolerated. The authors said high-quality data are lacking and larger trials are needed. Saw palmetto is anti-androgenic.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/33313047/","label":"PubMed: Natural hair supplement, friend or foe? Saw palmetto, a systematic review in alopecia (Evron et al., 2020)"}]},{"name":"Ashwagandha (safety)","text":"The NIH says ashwagandha may be safe short term (up to 3 months), long-term safety is unknown, and rare cases of liver injury have been linked to it. It should be avoided during pregnancy and breastfeeding, isn''t recommended for people with thyroid or autoimmune disorders or before surgery, and may interact with several medications.","citations":[{"url":"https://www.nccih.nih.gov/health/ashwagandha","label":"NIH NCCIH: Ashwagandha"}]}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb),
  ('p-magnumsolace-nighttime-magnesium-cream', 'Magnum Solace Nighttime Magnesium Cream', 'Magnum Solace', 'sleep', 'physical', 'A magnesium chloride body cream with shea butter and grapeseed oil, meant to be massaged into the legs, feet, arms or chest before bed. Magnum Solace says it eases muscle tension and restless legs and promotes relaxation and sleep, with 250 mg of magnesium per teaspoon. It comes in nine scents, including lavender, chamomile & lavender, and unscented. Made in small batches in Houston, Texas.', '$27.99 for 5 oz (list $39.99)', '/products/catalog/p-magnumsolace-nighttime-magnesium-cream.webp', 'https://www.magnumsolace.com/products/nighttime-magnesium-cream', '["sleep","magnesium","magnesium cream","muscle","restless legs","relaxation","lavender","unscented option","magnumsolace"]'::jsonb, '["sleep"]'::jsonb, '["magnumsolace.com","Walmart"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Cosmetic body cream; not an FDA-cleared drug or medical device. Magnum Solace''s claims that it relieves restless legs, muscle tension and sleep problems have not been evaluated by the FDA.","materials":"5 oz jar. Magnesium chloride (250 mg magnesium per teaspoon, per Magnum Solace) in a cream base of water, emulsifying wax, shea butter, grapeseed and sunflower oils, and vitamin E, preserved with phenoxyethanol.","recalls":"No recalls found.","sideEffects":"Magnum Solace says to avoid broken skin and freshly shaved areas. Scented versions add scent ingredients that aren''t in the published ingredient list; if you have sensitive skin, the unscented version avoids them. Full warnings are listed below.","opinionAlerts":"Magnum Solace says the cream delivers \"100% absorbable\" magnesium \"directly to the cellular level.\" A 2017 scientific review concluded that claims of magnesium absorption through the skin are scientifically unsupported. It may still feel soothing to massage in as a moisturizing bedtime cream."}'::jsonb, 'Magnum Solace says the cream eases muscle tension and restless legs and helps with sleep, because magnesium is absorbed through the skin, "100% absorbable" and delivered "directly to the cellular level."

The evidence for that absorption is weak. A 2017 review in Nutrients concluded that the promotion of transdermal magnesium is scientifically unsupported, while oral magnesium is well documented for treating deficiency. The only human trial found was a 2017 pilot of 25 people: a magnesium cream (56 mg a day for two weeks) raised blood magnesium slightly compared with a placebo cream, but the change was statistically significant only in a subgroup of non-athletes. One author has a financial interest in a different magnesium cream.

No study of this product, or of magnesium cream for sleep or restless legs, was found. Massaging in a rich cream at bedtime may still feel relaxing. If you have ongoing restless legs or trouble sleeping, it''s worth talking to a clinician.', 'Magnum Solace''s product page shows six featured five-star testimonials from verified buyers, mentioning better sleep, eased restless legs and cramps, and a non-greasy feel, for example: "It helps with cramping and restless legs, feels wonderful!" The page doesn''t show a total review count or average. It is also sold on Walmart, but Walmart blocks automated access, so no rating could be confirmed at time of writing.', 'No study of this cream, or of magnesium cream for sleep or restless legs, was found.', 'brand', 'Product claims are sourced from Magnum Solace; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"ingredients":"Full ingredient list per Magnum Solace: Purified Water (Aqua), Magnesium Chloride, Emulsifying Wax, Organic Butyrospermum Parkii (Shea Butter), Vitis Vinifera (Grape) Seed Oil, Tocopheryl Acetate (Vitamin E), Organic Helianthus Annuus (Sunflower) Oil, Phenoxyethanol. This published list contains no scent ingredients, so scented versions (such as Lavender) likely add essential oils or fragrance not listed here; check the jar.","doctorOpinionShort":"Its central claim, that magnesium absorbs through the skin, is unsupported according to a 2017 review; a small 2017 pilot found only a slight rise in blood magnesium. No study of this product or of magnesium cream for sleep was found. It may still work as a soothing bedtime massage cream.","doctorOpinionCitations":[{"url":"https://www.magnumsolace.com/products/nighttime-magnesium-cream","label":"magnumsolace.com: Nighttime Magnesium Cream, ingredients and claims"},{"url":"https://pubmed.ncbi.nlm.nih.gov/28788060/","label":"PubMed: Myth or reality, transdermal magnesium? (Nutrients 2017)","chipLabel":"Transdermal magnesium review (2017)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/28403154/","label":"PubMed: Effect of transdermal magnesium cream on serum and urinary magnesium levels, pilot study","chipLabel":"Magnesium cream pilot trial, 25 people (2017)"}],"whoItsFor":["People who like a rich, moisturizing massage cream as part of a bedtime routine","People who want an unscented option (one of its nine versions)","Not a substitute for seeing a clinician about ongoing restless legs, cramps or insomnia"],"howToUse":{"intro":"Per Magnum Solace: use every night for at least two weeks for best results.","steps":["Massage generously onto your legs, arms, chest or feet before going to sleep.","For restless legs, apply to your legs and the bottoms of your feet before bed.","Avoid broken skin and freshly shaved areas."],"sourceUrl":"https://www.magnumsolace.com/products/nighttime-magnesium-cream","sourceLabel":"magnumsolace.com: Nighttime Magnesium Cream"},"warnings":["Don''t apply to broken skin or freshly shaved areas (per Magnum Solace).","Sensitive skin or scent sensitivity: choose the unscented version or patch test first; scented versions'' added ingredients aren''t listed.","Ongoing restless legs, cramps or trouble sleeping: see a clinician to check for underlying causes."],"ingredientScience":[{"name":"Magnesium chloride (transdermal)","text":"Magnum Solace states its magnesium is absorbed through the skin. A 2017 review concluded that the promotion of transdermal magnesium is scientifically unsupported. A 2017 pilot of 25 people found a magnesium cream (56 mg a day for two weeks) raised blood magnesium slightly versus placebo, significant only in a subgroup of non-athletes; one author has a financial interest in a different magnesium cream.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28788060/","label":"PubMed: Myth or reality, transdermal magnesium? (Gröber et al., Nutrients 2017)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/28403154/","label":"PubMed: Effect of transdermal magnesium cream on serum and urinary magnesium levels in humans, pilot study (Kass et al., 2017)"}]}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://www.walmart.com/ip/17531958604","text":"Walmart: Magnum Solace Nighttime Magnesium Cream reviews","summary":"Customer reviews on Walmart. A rating couldn''t be confirmed at time of writing because Walmart blocks automated access."},{"platform":"website","url":"https://www.magnumsolace.com/products/nighttime-magnesium-cream","text":"magnumsolace.com: featured customer testimonials","summary":"Six featured five-star testimonials from verified buyers; no total count or average shown."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-infiniwell-ptd-dbm', 'InfiniWell PTD-DBM + Methyl Vanillate', 'InfiniWell', 'hair', 'physical', 'A leave-in scalp serum in a 25 mL dropper bottle, pairing the peptide PTD-DBM with methyl vanillate, a compound derived from vanillin. InfiniWell calls it physician-formulated and sells it as a cosmetic for fuller-looking hair, not as a hair-loss treatment. Apply to the scalp once a day; no rinsing. The research on PTD-DBM has only been done in cells and mice so far. InfiniWell offers a refund if you don''t feel a difference in 30 days.', '$69.95 for 25 mL', '/products/catalog/p-infiniwell-ptd-dbm.webp', 'https://infiniwell.com/products/ptd-dbm-methyl-vanillate', '["infiniwell","ptd-dbm","methyl vanillate","hair","scalp","hair serum","peptide","thinning","cosmetic"]'::jsonb, '["skin-hair"]'::jsonb, '["infiniwell.com","Amazon"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Sold as a cosmetic; not an FDA-approved drug for hair loss. InfiniWell says its statements haven''t been evaluated by the FDA and that the product isn''t formulated to treat hair loss.","materials":"25 mL serum with a dropper. InfiniWell says it is made in a cGMP facility in the USA and third-party tested by ISO-certified labs.","recalls":"No recalls found.","sideEffects":"For external use only; avoid contact with eyes. InfiniWell says to consult a physician first if you take prescription medication, have a medical condition, or are pregnant or nursing, and to check with a professional if you also use medicated hair treatments. Not for children.","opinionAlerts":"No human trial of PTD-DBM or of this serum was found. InfiniWell describes methyl vanillate two ways: as nourishing hair follicles, and as an ingredient that helps the serum spread and absorb."}'::jsonb, 'InfiniWell says PTD-DBM supports the Wnt/β-catenin pathway, a signaling pathway involved in hair follicle growth, and that the serum aims for visible results in less than 30 days. No study of this product was found.

PTD-DBM comes from a 2017 Journal of Investigative Dermatology study. Researchers found a protein called CXXC5 that slows hair regrowth and is raised in balding human scalp. In human hair cells, CXXC5 slowed cell growth; in mice, a peptide that blocks it sped up hair regrowth. A 2023 study by the same group found the peptide also reversed hair loss caused by DHT and prostaglandin D2 in mice. The senior researcher is CEO of a company licensed to develop the peptide. So far, PTD-DBM research has only been done in cells and mice.

The human evidence is for methyl vanillate: a 2016 uncontrolled, open-label study of 20 women with female pattern hair loss used a 0.2% methyl vanillate spray for 6 months. Hair count rose 6% and hair mass index 12% from baseline, with no dropouts for side effects. There was no placebo group, and InfiniWell doesn''t say how much methyl vanillate its serum contains.

If you have thinning hair, a dermatologist can check for causes and discuss treatments with stronger evidence, such as minoxidil.', 'InfiniWell''s page shows two sets of numbers. A stats card says 217 verified customers rated it 4.6 out of 5 on average, and 20% (about 1 in 5) mentioned thicker- or fuller-looking hair without being asked. InfiniWell says these reviews were collected by post-purchase email through July 2026 and that most reviewers received an incentive. Separately, the page header shows 4.9 stars from 1,136 reviews, which appear to cover InfiniWell''s products more broadly. On Amazon it has 3.3 out of 5 stars from 37 ratings.', 'One small, uncontrolled study supports methyl vanillate in women with pattern hair loss.', 'brand', 'Product claims are sourced from InfiniWell; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"infiniwell.com":"https://infiniwell.com/products/ptd-dbm-methyl-vanillate","Amazon":"https://www.amazon.com/InfiniWell-Hair-Growth-Serum-Restoration/dp/B09J97Z29F"},"ingredients":"Per InfiniWell: PTD-DBM (a peptide) and methyl vanillate. InfiniWell doesn''t list the full ingredients or the amount of either active as text on its product page.","doctorOpinionShort":"PTD-DBM has been tested only in cells and mice so far. Methyl vanillate has one small, uncontrolled study in 20 women (6% more hairs after 6 months). No study of this serum was found, and InfiniWell doesn''t publish its ingredient amounts.","doctorOpinionCitations":[{"url":"https://infiniwell.com/products/ptd-dbm-methyl-vanillate","label":"infiniwell.com: PTD-DBM + Methyl Vanillate, claims and FAQ"},{"url":"https://pubmed.ncbi.nlm.nih.gov/28595998/","label":"PubMed: Targeting of CXXC5 by a competing peptide stimulates hair regrowth and wound-induced hair neogenesis (J Invest Dermatol 2017)","chipLabel":"PTD-DBM cell and mouse study (2017)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/36831222/","label":"PubMed: CXXC5 mediates DHT-induced androgenetic alopecia via PGD2 (Cells 2023)","chipLabel":"PTD-DBM mouse study (2023)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/27121450/","label":"PubMed: Topical methyl vanillate increases hair count and hair mass index in women with androgenetic alopecia (J Cosmet Dermatol 2016)","chipLabel":"Methyl vanillate open-label study, 20 women (2016)"}],"whoItsFor":["People with thinning hair who want a non-drug cosmetic scalp serum and are comfortable with early-stage evidence","Not a substitute for seeing a dermatologist about new or fast hair loss","Pregnant or nursing: InfiniWell says to check with your physician first"],"howToUse":{"intro":"Per InfiniWell: use daily.","steps":["Apply evenly to the affected areas of the scalp once a day.","No need to rinse; it can be used with your usual shampoo and conditioner.","Avoid contact with eyes."],"sourceUrl":"https://infiniwell.com/products/ptd-dbm-methyl-vanillate","sourceLabel":"infiniwell.com: PTD-DBM + Methyl Vanillate"},"warnings":["External use only; avoid contact with eyes.","Pregnant, nursing, on prescription medication, or have a medical condition: consult your physician before use (per InfiniWell).","Using medicated hair-loss treatments such as minoxidil: check with a healthcare professional first (per InfiniWell).","Not for children."],"ingredientScience":[{"name":"PTD-DBM","text":"A peptide that blocks CXXC5, a protein that slows Wnt/β-catenin signaling and is raised in balding human scalp. In a 2017 study, CXXC5 slowed the growth of human hair follicle cells, and blocking it with the peptide sped up hair regrowth in mice. A 2023 study by the same group found it reversed hair loss caused by DHT and prostaglandin D2 in mice. The senior researcher is CEO of a company licensed to develop the peptide. So far, the research has only been done in cells and mice.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28595998/","label":"PubMed: Targeting of CXXC5 by a competing peptide stimulates hair regrowth and wound-induced hair neogenesis (Lee et al., J Invest Dermatol 2017)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/36831222/","label":"PubMed: CXXC5 mediates DHT-induced androgenetic alopecia via PGD2 (Ryu et al., Cells 2023)"}]},{"name":"Methyl vanillate","text":"In a 2016 uncontrolled, open-label study, 20 women aged 25 to 57 with female pattern hair loss used a spray with 0.2% methyl vanillate for 6 months. Hair count rose 6% and hair mass index 12% compared with baseline, and no one stopped because of side effects. There was no placebo group. InfiniWell doesn''t publish its serum''s methyl vanillate concentration.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/27121450/","label":"PubMed: Topical application of the Wnt/β-catenin activator methyl vanillate increases hair count and hair mass index in women with androgenetic alopecia (Tosti et al., 2016)"}]}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://infiniwell.com/products/ptd-dbm-methyl-vanillate","text":"infiniwell.com: PTD-DBM customer reviews","summary":"217 verified buyers average 4.6 out of 5, collected by post-purchase email; most reviewers received an incentive."},{"platform":"website","url":"https://www.amazon.com/InfiniWell-Hair-Growth-Serum-Restoration/dp/B09J97Z29F","text":"Amazon: InfiniWell PTD-DBM Peptide Hair Serum reviews","summary":"3.3 out of 5 stars from 37 ratings at time of writing."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-lilyeve-growturn-ampoule', 'Lilyeve Grow:Turn Ampoule (Hair Serum with Brush)', 'Lilyeve', 'hair', 'physical', 'A Korean leave-in scalp serum in a 100 mL tube with a built-in 38-bristle brush head for massaging it in. Lilyeve says it reduces hair shedding and flakes and soothes the scalp, using caffeine, heartleaf (which it calls exosome-derived) and a herbal blend it calls Scalp Clera. Apply to a damp scalp after shampooing, morning and evening. It''s sold for both men and women.', '$29.70', '/products/catalog/p-lilyeve-growturn-ampoule.webp', 'https://www.lilyeveus.com/products/lilyeve-antihairloss-growturn-ampoule100', '["lilyeve","growturn","grow:turn","hair","scalp","hair serum","thinning","shedding","caffeine","heartleaf","exosome","korean","cosmetic"]'::jsonb, '["skin-hair"]'::jsonb, '["lilyeveus.com","Amazon"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Sold as a cosmetic; not an FDA-approved drug for hair loss.","materials":"100 mL tube with a twist-lock brush head (38 bristles). The second ingredient is denatured alcohol, and it contains menthol and eucalyptus leaf oil even though Lilyeve markets it as fragrance-free.","recalls":"No recalls found.","sideEffects":"No warnings are published on Lilyeve''s product page. It contains denatured alcohol, menthol and eucalyptus oil, so patch test first if you have a sensitive scalp.","opinionAlerts":"Lilyeve''s results (75.61% less hair fall after 4 weeks, 89.04% less flaking) are from its own unpublished testing, with no details on how many people took part or whether there was a comparison group."}'::jsonb, 'Lilyeve says that, "based on clinical testing," four weeks of use cut hair fall by 75.61%, scalp flakiness by 89.04% and scalp irritation by 62.89%, and raised scalp hydration by 113.70%. It doesn''t say how many people were tested, whether there was a comparison group, or who ran the test, and no published study of this product was found.

Caffeine is the best-studied ingredient here. In a 2017 open-label randomized trial of 210 men with pattern hair loss, a 0.2% caffeine scalp liquid did about as well as 5% minoxidil after 6 months (anagen hairs improved 10.59% vs 11.68%). That trial was in men, and Lilyeve doesn''t publish its caffeine concentration.

Heartleaf (Houttuynia cordata) extract helped cultured human hair cells grow and kept lab-grown hair follicles in their growth phase longer in a 2019 lab study by a cosmetics company; it hasn''t been tested on people''s hair loss. Exosomes are a new area: a 2025 review found only 125 patients across the clinical studies of exosomes for hair loss and called for larger, well-designed trials. Lilyeve''s ingredient list doesn''t name an exosome ingredient.

If you have thinning hair, a dermatologist can check for causes and discuss treatments with stronger evidence, such as minoxidil.', 'On lilyeveus.com, 1,434 of 1,642 reviews (87%) are five stars, and 35 are one or two stars. On Amazon it has 4.1 out of 5 stars from 954 ratings. Reviews on Lilyeve''s site range from "seems to be working after a month" to "roots feel stronger but not like dramatic changes yet like in ads."', 'No published study of this serum was found. Its best-studied ingredient, topical caffeine, did about as well as minoxidil in one trial in men.', 'brand', 'Product claims are sourced from Lilyeve; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"lilyeveus.com":"https://www.lilyeveus.com/products/lilyeve-antihairloss-growturn-ampoule100","Amazon":"https://www.amazon.com/dp/B0DXPGSDZJ"},"ingredients":"Full ingredient list per Lilyeve: Water, Alcohol Denat., Butylene Glycol, Caffeine, 1,2-Hexanediol, Hydroxyacetophenone, PEG-60 Hydrogenated Castor Oil, Carbomer, Tromethamine, Menthol, Trideceth-10, Betaine, Disodium EDTA, Glycerin, Eucalyptus Globulus Leaf Oil, Camellia Japonica Flower Extract, Prunus Mume Flower Extract, Prunus Persica (Peach) Flower Extract, Althaea Rosea Flower Extract, Viola Mandshurica Flower Extract, Helianthus Annuus (Sunflower) Flower Extract, Houttuynia Cordata (Heartleaf) Extract, Cyananthus Atratus Extract, Inula Britannica Flower Extract, Lysimachia Foenum-graecum Extract. No exosome ingredient is named in this list, and two of the three Scalp Clera herbs Lilyeve names (Cimicifuga heracleifolia and Pogostemon cablin) aren''t in it either. The Amazon listing mentions biotin and peptides, which also aren''t in this list.","doctorOpinionShort":"Lilyeve''s results come from its own unpublished testing. Topical caffeine has one notable trial in 210 men, where it did about as well as minoxidil; heartleaf has been tested only in lab-grown hair cells, and exosomes for hair loss are still early. No published study of this serum was found.","doctorOpinionCitations":[{"url":"https://www.lilyeveus.com/products/lilyeve-antihairloss-growturn-ampoule100","label":"lilyeveus.com: Grow:Turn Ampoule, ingredients and claims"},{"url":"https://pubmed.ncbi.nlm.nih.gov/29055953/","label":"PubMed: Caffeine-based topical liquid 0.2% vs minoxidil 5% in male androgenetic alopecia, open-label randomized trial (Skin Pharmacol Physiol 2017)","chipLabel":"Caffeine vs minoxidil trial, 210 men (2017)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/31582654/","label":"PubMed: Hair growth promoting effect of Houttuynia cordata extract in cultured human hair follicle dermal papilla cells (Biol Pharm Bull 2019)","chipLabel":"Heartleaf lab study (2019)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/39447204/","label":"PubMed: Exosomes for treating hair loss, a review of clinical studies (Dermatol Surg 2025)","chipLabel":"Exosomes for hair loss review (2025)"}],"whoItsFor":["People with thinning hair or shedding who want a non-drug scalp serum with a built-in massage brush","People with a flaky or itchy scalp looking for a cooling, leave-in serum","Not a substitute for seeing a dermatologist about new or fast hair loss"],"howToUse":{"intro":"Per Lilyeve: use twice daily, morning and evening.","steps":["After shampooing, gently towel-dry your hair until damp.","Twist the brush head counterclockwise to unlock.","Apply directly to the scalp, focusing on thinning areas.","Twist the brush head clockwise to lock, then massage the scalp with the brush."],"sourceUrl":"https://www.lilyeveus.com/products/lilyeve-antihairloss-growturn-ampoule100","sourceLabel":"lilyeveus.com: Grow:Turn Ampoule"},"warnings":["Contains denatured alcohol, menthol and eucalyptus oil: patch test first if you have a sensitive scalp.","Using medicated hair-loss treatments such as minoxidil: check with a healthcare professional before combining."],"ingredientScience":[{"name":"Caffeine","text":"In a 2017 open-label, randomized trial of 210 men with pattern hair loss, a 0.2% caffeine scalp liquid was not inferior to 5% minoxidil after 6 months: the share of hairs in the growth (anagen) phase improved 10.59% with caffeine and 11.68% with minoxidil. The trial was in men only and wasn''t blinded. Lilyeve doesn''t publish its caffeine concentration.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29055953/","label":"PubMed: An open-label randomized multicenter study assessing the noninferiority of a caffeine-based topical liquid 0.2% versus minoxidil 5% solution in male androgenetic alopecia (Dhurat et al., 2017)"}]},{"name":"Heartleaf (Houttuynia cordata)","text":"In a 2019 lab study by researchers at LG Household & Healthcare, heartleaf extract made cultured human hair papilla cells multiply and kept lab-grown human hair follicles in their growth phase longer. It hasn''t been tested for hair loss in people.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31582654/","label":"PubMed: Hair growth promoting effect of Houttuynia cordata extract in cultured human hair follicle dermal papilla cells (Kim et al., 2019)"}]},{"name":"Exosomes","text":"A 2025 review of exosomes for hair loss found nine relevant clinical studies covering 125 patients in total. Side effects were rare, but the authors called for larger, well-designed trials and consistent manufacturing standards. Lilyeve says its exosomes come from heartleaf, but its ingredient list doesn''t name an exosome ingredient.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/39447204/","label":"PubMed: Exosomes for treating hair loss, a review of clinical studies (Queen & Avram, Dermatol Surg 2025)"}]}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://www.amazon.com/dp/B0DXPGSDZJ","text":"Amazon: lilyeve GROWTURN Hair Growth Serum reviews","summary":"4.1 out of 5 stars from 954 ratings at time of writing."},{"platform":"website","url":"https://www.lilyeveus.com/products/lilyeve-antihairloss-growturn-ampoule100","text":"lilyeveus.com: Grow:Turn customer reviews","summary":"1,642 reviews; 87% are five stars."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-heraure-hermag-magnesium', 'HerAuré HerMag Magnesium 20-in-1 Complex', 'HerAuré', 'supplement', 'physical', 'A daily magnesium capsule made for women, combining 12 forms of magnesium (led by magnesium glycinate) with a brain blend of L-theanine, lion''s mane, alpha-GPC, phosphatidylserine, PQQ, vitamin B6 and zinc, plus slippery elm. HerAuré says it supports relaxation, restful sleep, calm focus and steady energy. Take 2 capsules a day, which gives 300 mg of magnesium; a bottle lasts 45 days.', '$29.99 for 90 capsules (list $49.99)', '/products/heraure/hermag-magnesium.webp', 'https://heraure.com/products/hermag-magnesium-20-in-1-complex', '["heraure","hermag","magnesium","magnesium glycinate","l-theanine","lions mane","sleep","stress","relaxation","focus","supplement"]'::jsonb, '["supplement","sleep"]'::jsonb, '["heraure.com"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not evaluated by the FDA for safety or efficacy claims.","materials":"90 vegan capsules (2 a day, 45-day supply). Made in the USA, per the label.","recalls":"No recalls found.","sideEffects":"Each serving has 300 mg of magnesium, under the NIH''s 350 mg daily upper limit for magnesium from supplements; if you take other magnesium products, the total can go over it. The NIH says high supplement intakes can cause diarrhea, nausea and abdominal cramping. Full warnings are listed below.","opinionAlerts":"The label''s \"1685 mg\" and \"12x absorption\" claims aren''t explained on HerAuré''s product page, which lists 800 mg of magnesium compounds giving 300 mg of magnesium per serving."}'::jsonb, 'HerAuré says this formula supports relaxation, restful sleep, calm focus and steady energy. No study of this product was found, and HerAuré doesn''t list how much of each ingredient is in its blends, so what follows is what the research says about its main ingredients.

The evidence for magnesium and sleep is weak. A 2026 systematic review of 12 randomized trials concluded that current evidence doesn''t support oral magnesium as a routine treatment for insomnia; it may modestly help some people, but results were inconsistent and the certainty of evidence was low to very low. An earlier 2021 review of 3 trials in 151 older adults found people fell asleep about 17 minutes faster on magnesium than placebo, also with low-quality evidence.

L-theanine has somewhat more support: a 2025 meta-analysis of 18 trials (897 people) found small improvements in self-reported sleep quality and how quickly people fell asleep, though many studies didn''t test L-theanine alone. This product''s whole 7-ingredient brain blend is 135 mg, so its L-theanine dose is unknown.

If you have ongoing trouble sleeping, it''s worth talking to a clinician.', null, 'Evidence that magnesium improves sleep is low quality and inconsistent; L-theanine shows small benefits for self-reported sleep.', 'brand', 'Product claims are sourced from HerAuré; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"ingredients":"Per serving (2 capsules), per HerAuré: HerMag™ Magnesium Complex 800 mg (magnesium glycinate, malate, taurate, orotate, aspartate, lactate, ascorbate, gluconate, sulfate heptahydrate, citrate, oxide and chloride), providing 300 mg magnesium (71% DV). NeuroRadiance™ Blend 135 mg: L-theanine, lion''s mane mushroom extract, alpha-GPC, phosphatidylserine, PQQ (disodium salt), vitamin B6, zinc (as zinc picolinate). Slippery elm bark extract 50 mg. Other ingredients: HPMC vegetarian capsules, rice flour, magnesium stearate, silicon dioxide. The amounts of each magnesium form and each blend ingredient aren''t listed.","doctorOpinionShort":"Evidence that magnesium helps sleep is low quality and inconsistent; L-theanine has small benefits for self-reported sleep. HerAuré doesn''t publish the amount of each ingredient, and no study of this product was found. Its 300 mg of magnesium is under the NIH''s 350 mg daily supplement limit.","doctorOpinionCitations":[{"url":"https://heraure.com/products/hermag-magnesium-20-in-1-complex","label":"heraure.com: Magnesium 20-in-1 Complex, ingredients and claims"},{"url":"https://ods.od.nih.gov/factsheets/Magnesium-Consumer/","label":"NIH Office of Dietary Supplements: Magnesium, upper limits and interactions"},{"url":"https://pubmed.ncbi.nlm.nih.gov/42661485/","label":"PubMed: Magnesium supplementation for sleep in adults, systematic review of randomized controlled trials (J Diet Suppl 2026)","chipLabel":"Magnesium for sleep review, 12 trials (2026)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/33865376/","label":"PubMed: Oral magnesium supplementation for insomnia in older adults, systematic review and meta-analysis (BMC Complement Med Ther 2021)","chipLabel":"Magnesium for insomnia meta-analysis, 151 people (2021)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/40056718/","label":"PubMed: The effects of L-theanine consumption on sleep outcomes, systematic review and meta-analysis (Sleep Med Rev 2025)","chipLabel":"L-theanine sleep meta-analysis, 897 people (2025)"}],"whoItsFor":["Adults who want a magnesium supplement as part of a bedtime or daily routine","Pregnant, breastfeeding, on medication or managing a medical condition: HerAuré says to check with your healthcare professional first","Not a substitute for seeing a clinician about ongoing insomnia, anxiety or low energy"],"howToUse":{"intro":"Per HerAuré: take it consistently; any time of day works, though many people take it in the evening.","steps":["Take 2 capsules daily, with or without food."],"sourceUrl":"https://heraure.com/products/hermag-magnesium-20-in-1-complex","sourceLabel":"heraure.com: Magnesium 20-in-1 Complex"},"warnings":["Pregnant, breastfeeding, taking medication or managing a medical condition: talk with your healthcare professional first (per HerAuré).","Taking other magnesium supplements or magnesium-containing medicines: the NIH''s upper limit for magnesium from supplements and medications is 350 mg a day for adults, and this product alone has 300 mg.","Taking a bisphosphonate for osteoporosis: the NIH says these aren''t well absorbed when taken too close to a magnesium supplement, so ask about timing.","Diarrhea, nausea or cramping: the NIH lists these as effects of too much supplemental magnesium."],"ingredientScience":[{"name":"Magnesium (for sleep)","text":"A 2026 systematic review of 12 randomized trials found inconsistent results and low to very low certainty of evidence, and concluded that oral magnesium isn''t supported as a routine insomnia treatment, though it may modestly help some people. A 2021 meta-analysis of 3 trials in 151 older adults found magnesium cut the time to fall asleep by about 17 minutes versus placebo; total sleep time didn''t change significantly, and the evidence was low quality.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/42661485/","label":"PubMed: Magnesium supplementation for sleep in adults, a systematic review of randomized controlled trials (Lopresti et al., J Diet Suppl 2026)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/33865376/","label":"PubMed: Oral magnesium supplementation for insomnia in older adults, a systematic review & meta-analysis (Mah & Pitre, 2021)"}]},{"name":"Magnesium (safety)","text":"The NIH sets the upper limit for magnesium from supplements and medications at 350 mg a day for adults. Too much can cause diarrhea, nausea and abdominal cramping, and magnesium supplements can interfere with some medicines, such as bisphosphonates for osteoporosis.","citations":[{"url":"https://ods.od.nih.gov/factsheets/Magnesium-Consumer/","label":"NIH Office of Dietary Supplements: Magnesium fact sheet for consumers"}]},{"name":"L-theanine","text":"A 2025 meta-analysis of 18 randomized trials (897 people) found L-theanine made small improvements in self-reported sleep quality, time to fall asleep and daytime functioning. The authors noted few studies tested L-theanine on its own. HerAuré doesn''t list its L-theanine dose.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/40056718/","label":"PubMed: The effects of L-theanine consumption on sleep outcomes, a systematic review and meta-analysis (Bulman et al., Sleep Med Rev 2025)"}]}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-vpod-everyday-comfort-single', 'VPod Everyday Comfort Single Pack', 'VPod', 'intimate-care', 'physical', 'A reusable, drug-free cooling gel pod you freeze and place in your underwear for up to 20 minutes of relief from external vulvar and vaginal itching, burning, dryness, irritation, or swelling. The curved, flexible pod has a 100% medical-grade silicone exterior that stays in place without adhesive. VPod markets it for yeast infections, BV, allergies, perimenopause and menopause, pregnancy and postpartum, and after sex or workouts; it eases symptoms but doesn’t treat their cause. One pod per pack.', '$19.99 (1 pod)', '/products/catalog/p-vpod-everyday-comfort-single.webp', 'https://hervpod.com/products/vpod-regular-single-pack', '["discomfort","comfort","menopause","postpartum","external-only","reusable","hormone-free"]'::jsonb, '["vaginal-health","comfort"]'::jsonb, '["hervpod.com","Amazon","Walmart"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Registered with the FDA as an over-the-counter medical product, per hervpod.com. FDA registration means the company and product are listed with the FDA; it is not FDA clearance or approval.","materials":"Each pod is 3 in long x 2.5 in wide, with a 100% medical-grade silicone exterior and a flexible gel interior (the gel itself isn''t disclosed). Hypoallergenic, odor-free, and sterile when packaged. Made in China for Cool Comforts Co. (Cincinnati, OH).","recalls":"No recalls are mentioned on hervpod.com; check current FDA and manufacturer recall notices.","sideEffects":"Cold can feel too intense on sensitive skin, so VPod says to test the temperature first and limit each use to 20 minutes. Full warnings are listed below.","opinionAlerts":"hervpod.com contradicts itself on reuse: the product page says single-use and \"Do not reuse,\" but its FAQ and full instructions say the pod is reusable for up to 30 days with cleaning. ayna follows the detailed instructions; check the package insert."}'::jsonb, 'Cold therapy is a standard, low-risk way to ease vulvar and perineal soreness: ACOG recommends an ice pack or cold gel pack on the perineal area for 10 to 20 minutes at a time after birth, and a Cochrane review found cooling may reduce perineal pain in the first days postpartum (low-certainty evidence). VPod packages that idea as a curved silicone pod that stays in place in underwear.

Cooling only eases symptoms. It doesn''t treat yeast infections, BV, allergies, or menopause-related dryness, so it should be used alongside the right treatment, not instead of it. See a doctor for itching or burning that doesn''t go away, unusual discharge, or odor. VPod says it was developed with gynecologists; no study of VPod itself was found.', 'hervpod.com shows 6 customer reviews for this pod, all 5 stars; reviewers describe instant, mess-free relief while waiting for yeast-infection treatment to work, and one wished extra covers were easier to order. These are reviews on the brand’s own site. Amazon and Walmart listings are linked below; both block automated access, so ayna hasn’t pulled their ratings.', 'Cold therapy has category-level support for easing perineal pain (Cochrane; ACOG, linked below). No independent study of VPod was found, and cooling relieves symptoms only, not their underlying cause.', 'independent', 'ayna synthesis of ACOG guidance and a Cochrane review; not a direct clinician quote. Product details are from hervpod.com.', 'curated', false, false, null, false, '{"affiliateUrl":"https://collabs.shop/bxd4fg","faqUrl":"https://hervpod.com/pages/faq","doctorOpinionShort":"Cold packs are an ACOG-recommended way to ease perineal soreness, and a Cochrane review found cooling may reduce postpartum perineal pain. VPod relieves symptoms but doesn''t treat their cause. No study of VPod itself was found.","whoItsFor":["Short-term relief from external vulvar itching, burning, swelling, or soreness","Discomfort from a yeast infection or BV while treatment starts working","Perimenopause and menopause discomfort, and irritation after sex, workouts, or on hot days","Anyone who wants drug-free, mess-free relief instead of creams or padsicles"],"howToUse":{"intro":"Per VPod''s full instructions:","steps":["Put the unopened foil pack in the freezer for at least 1 hour, until the pod feels stiff.","Take it out and let it rest 3 to 5 minutes, then wash your hands and open the pack.","Touch the pod gently to your vulva first to check the temperature is comfortable.","Place it between the inner and outer labia (labia minora and majora), or in the center crotch of your underwear.","Wear it for up to 20 minutes, up to 3 times a day, waiting at least 10 minutes between uses.","After each use, rinse with warm water, wash with mild soap, and air dry; wipe with 70% isopropyl alcohol at least daily. Replace the pod after 30 days or if damaged."],"sourceUrl":"https://hervpod.com/pages/usage-instructions","sourceLabel":"hervpod.com: Instructions for Use"},"warnings":["External use only. Do not insert into the vagina or anus, and do not ingest.","For temporary symptom relief only; it does not treat yeast infections, BV, or other conditions. See a doctor for itching or burning that doesn’t go away, unusual discharge, or odor.","Remove before urinating, and don’t flush it.","Don’t use with other silicone-based products.","If the pod ruptures, clean the skin and throw the pod away (the gel may be slippery)."],"ingredients":"Medical-grade silicone exterior with a gel interior (gel not disclosed). Drug-free; no active ingredients.","scientificCitations":[],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8094618/","text":"Local cooling for relieving pain from perineal trauma sustained during childbirth (Cochrane review, 2020)","summary":"A Cochrane review of 10 randomized trials (1,233 women) found that cooling with an ice pack or cold gel pad may reduce perineal pain in the first two days after birth, but the evidence is low to very low certainty. This is evidence for cold therapy in general, not for VPod specifically."},{"url":"https://www.acog.org/womens-health/faqs/postpartum-pain-management","text":"ACOG: Postpartum Pain Management","summary":"ACOG recommends applying an ice pack or cold gel pack to the perineal area for 10 to 20 minutes at a time to relieve discomfort after birth. This is clinical guidance for cold therapy as a category, not validation of a specific product."},{"url":"https://www.acog.org/womens-health/faqs/vulvovaginal-health","text":"ACOG: Vulvovaginal Health","summary":"ACOG suggests cold packs for perineal pain and advises seeing an ob-gyn for itching, burning, or swelling that doesn’t go away, since yeast infections, BV, and other causes need their own treatment. Cooling eases symptoms but doesn’t treat the cause.","justification":"Conservative ayna classification: category or adjacent evidence only; this source does not validate this specific product."}]},"community":{"links":[{"platform":"tiktok","url":"https://www.tiktok.com/tag/vpod","text":"TikTok: #vpod","summary":"TikTok posts tagged #vpod. The hashtag isn''t exclusive to this brand, so some posts may be about unrelated products; TikTok blocks automated access, so ayna hasn''t reviewed them."},{"platform":"amazon","url":"https://www.amazon.com/dp/B0F9YXP4MR","text":"Amazon: VPod Reusable Feminine Cooling Gel Pods, 1 Count","summary":"This pod’s Amazon listing, with customer ratings and reviews. Amazon blocks automated access, so no rating is quoted here; read the reviews directly."},{"platform":"walmart","url":"https://www.walmart.com/ip/Vpod-Single-Pack/17868111516","text":"Walmart: VPod Single Pack","summary":"This pod’s Walmart listing, with customer reviews. The site blocks automated access, so no rating is quoted here; read the reviews directly."},{"platform":"website","url":"https://hervpod.com/products/vpod-regular-single-pack","text":"hervpod.com: VPod Everyday Comfort Single Pack","summary":"VPod’s own product page, which shows 6 customer reviews, all 5 stars."}]}},"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb),
